function Modal({title,subtitle,onClose,children,wide=false}){const modalRef=useRef(null),closeTimer=useRef(null);const [closing,setClosing]=useState(false);const dismiss=()=>{if(closeTimer.current)return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){onClose();return}setClosing(true);closeTimer.current=setTimeout(onClose,180)};useEffect(()=>{const previous=document.activeElement;const list=()=>[...modalRef.current.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex="0"]')].filter(e=>e.offsetParent!==null);list()[0]?.focus();const f=e=>{if(e.key==='Escape')dismiss();if(e.key==='Tab'){const items=list(),first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};window.addEventListener('keydown',f);return()=>{clearTimeout(closeTimer.current);window.removeEventListener('keydown',f);previous?.focus({preventScroll:true})}},[]);return <div className={`modal-backdrop ${closing?'is-closing':''}`} onMouseDown={e=>{if(e.target===e.currentTarget)dismiss()}}><section ref={modalRef} className={`modal ${wide?'wide':''} ${closing?'is-closing':''}`} role="dialog" aria-modal="true" aria-label={title}><header><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><IconButton icon={X} label="关闭对话框" onClick={dismiss}/></header>{children}</section></div>}
